&lt;ul&gt;&lt;li&gt;&lt;b&gt;Type&lt;/b&gt; ingestion ; &lt;b&gt;D&#233;pendance&lt;/b&gt; mod&#233;r&#233;e, &lt;b&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Valeurs-De-Combat#Jetdesauvegarde.html&quot; title=&quot;Vigueur&quot;&gt;Vigueur&lt;/a&gt;&lt;/b&gt; &lt;a class=&quot;pagelink&quot; href=&quot;Vocabulaire-Courant#Degrededifficulte.html&quot; title=&quot;DD&quot;&gt;DD&lt;/a&gt; 18&lt;/li&gt;&lt;li&gt;&lt;b&gt;Prix&lt;/b&gt; 60 po&lt;/li&gt;&lt;li&gt;&lt;b&gt;Effet&lt;/b&gt; 1 heure ; +1d4 points de &lt;a class=&quot;pagelink&quot; href=&quot;Caract&#233;ristiques#Charisme.html&quot; title=&quot;Le Charisme&quot;&gt;Charisme&lt;/a&gt; et +1 point de &lt;a class=&quot;pagelink&quot; href=&quot;Caract&#233;ristiques#Dexterite.html&quot; title=&quot;La Dext&#233;rit&#233;&quot;&gt;Dext&#233;rit&#233;&lt;/a&gt;&lt;/li&gt;&lt;li&gt;&lt;b&gt;D&#233;g&#226;ts&lt;/b&gt; 1d2 points d’&lt;a class=&quot;pagelink&quot; href=&quot;Affaiblissement-Temporaire-(Capacit&#233;).html&quot; title=&quot;affaiblissement temporaire&quot;&gt;affaiblissement temporaire&lt;/a&gt; d&#39;&lt;a class=&quot;pagelink&quot; href=&quot;Caract&#233;ristiques#Intelligence.html&quot; title=&quot;L&amp;#39;Intelligence&quot;&gt;Intelligence&lt;/a&gt;&lt;br /&gt;&lt;/li&gt;&lt;/ul&gt;&lt;br /&gt;Ces pastilles ambr&#233;es augmentent l&#233;g&#232;rement l’agilit&#233;, ainsi que la beaut&#233; et l’&#233;loquence, de l’utilisateur. Les prostitu&#233;es abusent souvent de cette drogue, d’o&#249; son nom, et les douceurs de la catin gagnent &#233;galement en popularit&#233; dans certains cercles de l’aristocratie.
&lt;/div&gt;&lt;br /&gt;&lt;div class=&quot;BD&quot;&gt;
&lt;div class=&quot;ref right&quot; style=&quot;padding: 0 0 3px 3px;&quot;&gt;&lt;a name=&quot;ECORCHEFEUILLE&quot; href=&quot;#ECORCHEFEUILLE&quot;&gt;&lt;img class=&quot;opachover&quot; src=&quot;/images/pathfinder/wiki/logoref.png&quot; width=&quot;12px&quot; style=&quot;opacity:0.1&quot;&gt;&lt;/a&gt;&lt;/div&gt;&lt;div class=&quot;BDtitre&quot;&gt;&#201;corchefeuille&lt;div style=&quot;float:right;&quot;&gt;&lt;/div&gt;&lt;/div&gt;
